### 练习 2：用指针遍历数组（下标和指针两种方式）

```c
#include <stdio.h>

int main()
{
    int arr[] = {10, 20, 30, 40, 50, 60};
    int len = sizeof(arr) / sizeof(arr[0]);

    // 方式一：下标法（使用数组下标访问）
    printf("下标法: ");
    for (int i = 0; i < len; i++)
    {
        printf("%d ", arr[i]);
    }
    printf("\n");

    // 方式二：指针法（使用指针算术遍历）
    printf("指针法: ");
    int *p = arr;
    for (int i = 0; i < len; i++)
    {
        printf("%d ", *(p + i));  // 或 p[i]
    }
    printf("\n");

    // 方式三：指针移动法（直接移动指针）
    printf("移动指针: ");
    for (int *q = arr; q < arr + len; q++)
    {
        printf("%d ", *q);
    }
    printf("\n");

    return 0;
}
```

