## 函数指针

函数指针是指向函数的指针。函数名在表达式中会自动退化为指向该函数的指针（和数组名类似）。

### 定义语法

```c
int (*fp)(int, int);
```

解读：`fp` 先与 `*` 结合（括号），表明 `fp` 是指针；右边 `(int, int)` 表明它指向一个接受两个 `int` 参数、返回 `int` 的函数。

### 赋值与调用

```c
#include <stdio.h>

int add(int a, int b) { return a + b; }

int main(void)
{
    int (*fp)(int, int);

    // 两种赋值方式等价
    fp = add;    // 函数名退化为指针
    fp = &add;   // 显式取地址（与上面完全等价）

    // 两种调用方式等价
    int r1 = fp(3, 5);    // 直接调用
    int r2 = (*fp)(3, 5); // 显式解引用后调用（极少这么写，但合法）

    printf("%d  %d\n", r1, r2);  // 8  8
    return 0;
}
```

### 回调函数：函数指针作为参数

回调函数是最常见的函数指针应用——将一个函数的指针传递给另一个函数，由后者在适当的时候调用。

```c
#include <stdio.h>

int add(int a, int b) { return a + b; }
int sub(int a, int b) { return a - b; }
int mul(int a, int b) { return a * b; }

// 回调函数参数
int calculate(int x, int y, int (*operation)(int, int))
{
    return operation(x, y);   // 通过函数指针调用
}

int main(void)
{
    printf("10 + 5 = %d\n", calculate(10, 5, add));
    printf("10 - 5 = %d\n", calculate(10, 5, sub));
    printf("10 * 5 = %d\n", calculate(10, 5, mul));
    return 0;
}
```

### qsort 示例

标准库 `qsort` 使用函数指针实现泛型排序：

```c
#include <stdio.h>
#include <stdlib.h>

int cmp_int_asc(const void *a, const void *b)
{
    int ia = *(const int *)a;
    int ib = *(const int *)b;
    return (ia > ib) - (ia < ib);  // 安全：无符号溢出和符号溢出都是UB，但这里用比较避免了减法溢出
}

int cmp_int_desc(const void *a, const void *b)
{
    int ia = *(const int *)a;
    int ib = *(const int *)b;
    return (ib > ia) - (ib < ia);
}

int main(void)
{
    int arr[] = {7, 2, 9, 1, 5, 6};
    size_t n = sizeof(arr) / sizeof(arr[0]);

    qsort(arr, n, sizeof(int), cmp_int_asc);
    for (size_t i = 0; i < n; i++)
        printf("%d ", arr[i]);
    printf("\n");

    qsort(arr, n, sizeof(int), cmp_int_desc);
    for (size_t i = 0; i < n; i++)
        printf("%d ", arr[i]);
    printf("\n");

    return 0;
}
```

### 函数指针数组实现简单状态机

在嵌入式开发中，状态机的实现常用函数指针数组，每个状态对应一个处理函数：

```c
#include <stdio.h>
#include <unistd.h>

// 状态枚举
typedef enum {
    STATE_IDLE,
    STATE_RUNNING,
    STATE_ERROR,
    STATE_COUNT
} state_t;

// 每个状态的处理函数
state_t state_idle(void)
{
    printf("[IDLE] 等待指令...\n");
    sleep(1);
    return STATE_RUNNING;  // 切换到下一个状态
}

state_t state_running(void)
{
    printf("[RUNNING] 执行中...\n");
    sleep(1);
    return STATE_IDLE;
}

state_t state_error(void)
{
    printf("[ERROR] 错误处理...\n");
    return STATE_IDLE;
}

int main(void)
{
    // 函数指针数组：状态表
    state_t (*state_table[STATE_COUNT])(void) = {
        state_idle,
        state_running,
        state_error
    };

    state_t current = STATE_IDLE;

    for (int step = 0; step < 5; step++) {
        current = state_table[current]();  // 通过函数指针数组调用
    }

    return 0;
}
```

### 嵌入式回调：定时器与 ADC

```c
#include <stdio.h>

// 模拟：定时器中断回调
typedef void (*timer_callback_t)(void);

void timer0_isr(void)
{
    printf("Timer0 触发！\n");
}

void timer1_isr(void)
{
    printf("Timer1 触发！\n");
}

void register_timer(int timer_id, timer_callback_t cb)
{
    printf("注册 Timer%d 的回调函数\n", timer_id);
    // 实际嵌入式代码会将 cb 存入中断向量表
}

int main(void)
{
    register_timer(0, timer0_isr);
    register_timer(1, timer1_isr);

    // 模拟中断触发
    printf("\n=== 中断响应 ===\n");
    timer0_isr();
    timer1_isr();
    return 0;
}
```

