### 练习 4：实现 `trim` 函数

**要求：** 去掉字符串首尾的空白字符（空格、制表符 `\t`、换行符 `\n`）。要求直接修改原字符串。

```c
#include <stdio.h>
#include <string.h>

// 判断字符是否为空白
static int is_whitespace(char c)
{
    return c == ' ' || c == '\t' || c == '\n' || c == '\r';
}

// 去掉首尾空白（直接修改原字符串）
char *trim(char *s)
{
    if (s == NULL) return NULL;

    char *end;

    // 去掉开头空白
    while (is_whitespace(*s)) {
        s++;
    }

    // 如果全是空白，返回空字符串
    if (*s == '\0') {
        return s;
    }

    // 去掉结尾空白
    end = s + strlen(s) - 1;
    while (end > s && is_whitespace(*end)) {
        end--;
    }

    // 添加新的结尾 '\0'
    *(end + 1) = '\0';

    return s;
}

// 测试
int main(void)
{
    char s1[] = "   hello world   \n";
    printf("'%s'\n", trim(s1));  // 'hello world'

    char s2[] = "\t\t  ";
    printf("'%s'\n", trim(s2));  // ''

    char s3[] = "no trim";
    printf("'%s'\n", trim(s3));  // 'no trim'

    return 0;
}
```

