## 枚举（enum）

### 定义

枚举定义一组命名的整数常量。默认从 0 开始递增。

```c
#include <stdio.h>

// 默认值
enum Color { RED, GREEN, BLUE };
// RED = 0, GREEN = 1, BLUE = 2

// 指定起始值
enum Weekday {
    MON = 1,
    TUE,        // = 2
    WED,        // = 3
    THU,        // = 4
    FRI,        // = 5
    SAT,        // = 6
    SUN         // = 7
};

// 不连续的值
enum ErrorCode {
    SUCCESS     = 0,
    ERR_NULL    = -1,
    ERR_TIMEOUT = -2,
    ERR_IO      = -5
};

int main(void) {
    enum Color c = RED;
    enum Weekday today = MON;

    printf("RED = %d\n", RED);       // 0
    printf("MON = %d\n", MON);       // 1
    printf("SUN = %d\n", SUN);       // 7

    printf("c = %d, today = %d\n", c, today);  // c = 0, today = 1

    return 0;
}
```

### 枚举 vs `#define`

| 对比维度 | 枚举 | `#define` |
|----------|------|-----------|
| 类型安全性 | 有（弱类型，编译器可以检查） | 无（纯粹的文本替换） |
| 调试符号 | 有（调试器可显示枚举名） | 无（预处理后常量名消失） |
| 作用域 | 遵循块作用域规则 | 全局替换（无作用域） |
| 存储 | 占用整数类型空间 | 不占用存储（编译时常量） |
| 适用场景 | 一组相关的命名常量 | 通用的宏定义 |

```c
#include <stdio.h>

// #define：在预处理阶段替换，调试时看不到常量名
#define STATE_IDLE    0
#define STATE_RUNNING 1
#define STATE_STOPPED 2

// enum：编译期类型，调试器可以显示枚举名
enum State {
    STATE_IDLE_ENUM,
    STATE_RUNNING_ENUM,
    STATE_STOPPED_ENUM
};

// enum 的优势：可以限制参数类型（虽然是弱限制）
void process_state(enum State s) {
    switch (s) {
        case STATE_IDLE_ENUM:
            printf("IDLE\n");
            break;
        case STATE_RUNNING_ENUM:
            printf("RUNNING\n");
            break;
        case STATE_STOPPED_ENUM:
            printf("STOPPED\n");
            break;
    }
}
```

### 嵌入式状态机示例

```c
#include <stdio.h>

enum FsmState {
    STATE_INIT,
    STATE_CONFIG,
    STATE_RUN,
    STATE_ERROR,
    STATE_SLEEP
};

const char *state_name(enum FsmState s) {
    switch (s) {
        case STATE_INIT:   return "INIT";
        case STATE_CONFIG: return "CONFIG";
        case STATE_RUN:    return "RUN";
        case STATE_ERROR:  return "ERROR";
        case STATE_SLEEP:  return "SLEEP";
        default:           return "UNKNOWN";
    }
}

struct Fsm {
    enum FsmState state;
    int counter;
};

void fsm_step(struct Fsm *fsm) {
    switch (fsm->state) {
        case STATE_INIT:
            fsm->state = STATE_CONFIG;
            break;
        case STATE_CONFIG:
            fsm->state = STATE_RUN;
            break;
        case STATE_RUN:
            if (++fsm->counter >= 10) {
                fsm->state = STATE_SLEEP;
            }
            break;
        case STATE_ERROR:
            break;
        case STATE_SLEEP:
            break;
    }
    printf("State: %s\n", state_name(fsm->state));
}

int main(void) {
    struct Fsm fsm = {STATE_INIT, 0};
    for (int i = 0; i < 15; i++) {
        fsm_step(&fsm);
    }
    return 0;
}
```

### 枚举的注意事项

- **枚举的大小**：C 标准规定枚举常量是 `int` 类型。所有枚举变量的实际大小是实现定义的，但通常是 `int` 的大小。
- **不能前向声明**：C 语言不支持枚举的前向声明（C++11 支持有底层类型的枚举前向声明，但 C 不支持）。
- **枚举可以赋任意 int 值**：枚举变量可以存储不在枚举列表中的整数值（编译器通常只给警告）。

