## typedef

### 基本用法

`typedef` 为已有类型创建别名，不创建新类型，只是语法层面的别名。

```c
#include <stdio.h>

// 基本类型别名
typedef unsigned int      uint32_t;
typedef unsigned long     uint64_t;  // 注意：实际大小取决于平台
typedef unsigned char     byte;

// 在嵌入式开发中，常使用 stdint.h 提供的标准类型
// #include <stdint.h>
// uint32_t, uint16_t, uint8_t, int32_t, ...

int main(void) {
    uint32_t count = 100;
    byte data = 0xAB;
    printf("count = %u, data = 0x%02X\n", count, data);
    return 0;
}
```

### 简化复杂声明

`typedef` 最大的价值在于简化难以阅读的复杂类型声明。

```c
#include <stdio.h>

// 函数指针类型
// 不使用 typedef:
// int (*op)(int, int);
// 如果要声明多个函数指针变量：
// int (*add)(int, int), (*sub)(int, int);  // 语法很奇怪

// 使用 typedef:
typedef int (*Operation)(int, int);

int add(int a, int b) { return a + b; }
int sub(int a, int b) { return a - b; }

int main(void) {
    Operation op1 = add;
    Operation op2 = sub;

    printf("add(3, 5) = %d\n", op1(3, 5));   // 8
    printf("sub(3, 5) = %d\n", op2(3, 5));   // -2

    // 函数指针数组
    Operation ops[] = {add, sub};
    printf("ops[0](10, 20) = %d\n", ops[0](10, 20));  // 30

    return 0;
}
```

### 为结构体创建别名

```c
// 不使用 typedef：每个地方都要加 struct
struct Point {
    int x;
    int y;
};
struct Point p1;  // 必须写 struct

// 使用 typedef：
typedef struct {
    int x;
    int y;
} Point;

Point p1;         // 不需要 struct 关键字
Point p2 = {10, 20};

// 也可以保留结构体标签，有时需要自引用
typedef struct Node {
    int data;
    struct Node *next;  // 在 typedef 定义完成前，必须使用 struct Node
} Node;
```

### typedef vs `#define`

| 对比维度 | typedef | `#define` |
|----------|---------|-----------|
| 处理阶段 | 编译期（由编译器处理） | 预处理期（文本替换） |
| 作用域 | 遵循块作用域 | 全局替换（直到 `#undef`） |
| 类型检查 | 有（编译器理解别名） | 无（纯文本替换） |
| 能力 | 只能为类型创建别名 | 可以做任何文本替换 |

```c
#include <stdio.h>

// #define 的陷阱
#define INT_PTR int*
INT_PTR a, b;   // 展开为：int* a, b;
                // a 是 int*，b 是 int（不是指针！）

// typedef 正确处理
typedef int* int_ptr;
int_ptr c, d;   // c 和 d 都是 int*

int main(void) {
    int x = 42;

    a = &x;  // OK：a 是 int*
    // b = &x;  // 错误：b 是 int，不能赋值为指针

    c = &x;  // OK
    d = &x;  // OK：d 也是 int*

    return 0;
}
```

### 可移植类型

```c
#include <stdio.h>

// 根据平台定义可移植类型
#if defined(__linux__)
    typedef unsigned long long uint64;
    // 或在不同平台上 int 大小不同时：
    // typedef int int32;   // 32-bit
    // typedef long long int64;
#elif defined(_WIN32)
    typedef unsigned __int64 uint64;
#endif

int main(void) {
    // 建议直接使用 <stdint.h> 中定义的标准类型
    // uint64_t, int32_t, uint16_t, uint8_t
    printf("sizeof(uint64_t) = %zu\n", sizeof(uint64_t));
    return 0;
}
```

> 嵌入式建议：优先使用 `<stdint.h>` 中定义的定宽整数类型（`uint8_t`、`uint16_t`、`uint32_t`、`uint64_t` 等），避免跨平台和跨编译器的类型大小差异。

### 不要隐藏指针

```c
// 不好的做法：typedef 隐藏了指针
typedef int* IntPtr;

void func(void) {
    IntPtr a, b;  // a 是 int*, b 也是 int* —— 这看起来很"正常"
    // 但当作为参数时：
    // void foo(IntPtr p);  // 调用者看不出 p 是指针！
    // 容易写出：foo(NULL); 而不知道在传递指针
}

// 更好的做法：保留指针的可见性
typedef struct Device Device;

// 函数签名明确显示返回指针
Device *device_create(void);
void    device_destroy(Device *dev);
```

> **最佳实践**：如果 typedef 隐藏了指针、引用或数组，会让代码的语义不易理解。只在明确需要封装（如不透明指针模式）时才隐藏指针。

