## 文件操作基础

### FILE* 流模型

C 语言使用 `FILE *` 指针表示文件流。所有文件操作都包含三个步骤：

```
打开文件 (fopen) → 读写操作 → 关闭文件 (fclose)
```

### fopen 模式

```c
#include <stdio.h>

int main(void) {
    FILE *fp = NULL;

    // "r"  只读。文件必须存在。文本模式
    // "w"  只写。文件存在则清空，不存在则创建。文本模式
    // "a"  追加。文件不存在则创建。文本模式
    // "rb" 只读。二进制模式
    // "wb" 只写。二进制模式
    // "ab" 追加。二进制模式
    // "r+" 读写。文件必须存在。不会清空文件
    // "w+" 读写。文件存在则清空，不存在则创建
    // "a+" 读和追加。文件不存在则创建

    // 打开文件
    fp = fopen("test.txt", "w");
    if (fp == NULL) {
        perror("fopen");
        return 1;
    }

    // 写入数据
    fprintf(fp, "Hello, world!\n");

    // 关闭文件
    fclose(fp);
    fp = NULL;  // 防止悬空指针

    return 0;
}
```

### 文本模式 vs 二进制模式

在 POSIX 系统（Linux、macOS）上，文本模式和二进制模式没有区别。但在 Windows 上：

- **文本模式**：`\n`（换行符）在写入时被转换为 `\r\n`（回车+换行），读取时 `\r\n` 被转换为 `\n`。
- **二进制模式**：不做任何转换。

```c
// 在 Windows 上可能引起问题的场景
FILE *fp = fopen("data.bin", "w");   // 文本模式！
fwrite(buf, 1, 256, fp);
// 如果 buf 中有 0x0A（\n），会被转换为 0x0D 0x0A
// 读取时 0x0D 0x0A 会被合并为 0x0A
// 这会导致二进制数据损坏

// 正确做法：二进制文件用 "wb" / "rb"
FILE *fp2 = fopen("data.bin", "wb");
```

### 文件读写函数一览

| 类别 | 函数 | 说明 |
|------|------|------|
| 二进制 I/O | `fread(buf, size, count, fp)` | 从文件读取 `count` 个大小为 `size` 的数据块 |
| 二进制 I/O | `fwrite(buf, size, count, fp)` | 向文件写入 `count` 个大小为 `size` 的数据块 |
| 格式化 I/O | `fprintf(fp, fmt, ...)` | 格式化写入文本 |
| 格式化 I/O | `fscanf(fp, fmt, ...)` | 格式化读取文本 |
| 行 I/O | `fgets(buf, n, fp)` | 读取一行（包含换行符，最多 n-1 字符） |
| 行 I/O | `fputs(str, fp)` | 写入字符串（不自动添加换行符） |
| 字符 I/O | `fgetc(fp)` | 读取一个字符（返回 int，EOF 表示结束） |
| 字符 I/O | `fputc(c, fp)` | 写入一个字符 |
| 定位 | `fseek(fp, offset, whence)` | 移动文件位置指针 |
| 定位 | `ftell(fp)` | 返回当前文件位置 |
| 定位 | `rewind(fp)` | 回到文件开头 |

### 二进制 I/O：fread / fwrite

```c
#include <stdio.h>
#include <string.h>

struct Record {
    int id;
    char name[32];
    double value;
};

int main(void) {
    // 写入二进制文件
    FILE *fp = fopen("records.bin", "wb");
    if (fp == NULL) {
        perror("fopen");
        return 1;
    }

    struct Record recs[] = {
        {1, "Alpha", 10.5},
        {2, "Beta",  20.3},
        {3, "Gamma", 30.8}
    };
    size_t written = fwrite(recs, sizeof(struct Record), 3, fp);
    if (written != 3) {
        perror("fwrite");
    }
    fclose(fp);

    // 读取二进制文件
    fp = fopen("records.bin", "rb");
    if (fp == NULL) {
        perror("fopen");
        return 1;
    }

    struct Record buf[3];
    size_t read = fread(buf, sizeof(struct Record), 3, fp);
    if (read != 3 && ferror(fp)) {
        perror("fread");
    }

    for (size_t i = 0; i < read; i++) {
        printf("id=%d, name=%s, value=%.1f\n",
               buf[i].id, buf[i].name, buf[i].value);
    }

    fclose(fp);
    return 0;
}
```

> **注意**：直接使用 `fwrite` 写入结构体时，如果该结构体有 padding（填充字节），写入的文件也会包含这些 padding。不同平台 padding 不同，跨平台交换数据时需使用 packed 结构体或手动序列化。

### 格式化 I/O：fprintf / fscanf

```c
#include <stdio.h>

int main(void) {
    // 写入
    FILE *fp = fopen("data.txt", "w");
    if (fp == NULL) return 1;

    int id = 101;
    char name[] = "张三";
    double score = 88.5;

    fprintf(fp, "%d,%s,%.1f\n", id, name, score);
    fclose(fp);

    // 读取
    fp = fopen("data.txt", "r");
    if (fp == NULL) return 1;

    int rid;
    char rname[32];
    double rscore;
    if (fscanf(fp, "%d,%31[^,],%lf", &rid, rname, &rscore) == 3) {
        printf("读取: id=%d, name=%s, score=%.1f\n", rid, rname, rscore);
    }

    fclose(fp);
    return 0;
}
```

### 行 I/O：fgets / fputs

```c
#include <stdio.h>

int main(void) {
    // 写入多行
    FILE *fp = fopen("lines.txt", "w");
    if (fp == NULL) return 1;

    fputs("第一行\n", fp);
    fputs("第二行\n", fp);
    fputs("第三行\n", fp);
    fclose(fp);

    // 逐行读取
    fp = fopen("lines.txt", "r");
    if (fp == NULL) return 1;

    char line[256];
    int line_num = 0;
    while (fgets(line, sizeof(line), fp)) {
        line_num++;
        // fgets 保留换行符，可以用如下方式去除：
        // line[strcspn(line, "\n")] = '\0';
        printf("第%d行: %s", line_num, line);
    }
    fclose(fp);

    return 0;
}
```

### 文件定位：fseek / ftell / rewind

```c
#include <stdio.h>

int main(void) {
    FILE *fp = fopen("test.bin", "wb+");
    if (fp == NULL) return 1;

    // 写入一些数据
    int data[] = {10, 20, 30, 40, 50};
    fwrite(data, sizeof(int), 5, fp);

    // ftell：当前文件位置
    long pos = ftell(fp);
    printf("写完后位置: %ld（应为 %zu）\n", pos, 5 * sizeof(int));

    // rewind：回到文件开头
    rewind(fp);
    printf("rewind后位置: %ld\n", ftell(fp));

    // fseek：移动到指定偏移
    // SEEK_SET：从文件开头算起
    // SEEK_CUR：从当前位置算起
    // SEEK_END：从文件末尾算起

    // 读取第三个元素（索引 2）
    int val;
    fseek(fp, 2 * sizeof(int), SEEK_SET);  // 偏移到索引 2
    fread(&val, sizeof(int), 1, fp);
    printf("data[2] = %d\n", val);  // 30

    // 获取文件大小
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    printf("文件大小: %ld 字节\n", file_size);

    fclose(fp);
    return 0;
}
```

