## 嵌入式中的结构体

### 外设寄存器映射

这是嵌入式 C 中最经典的结构体用法。将外设的寄存器空间映射为一个结构体，通过结构体指针访问寄存器。

```c
#include <stdint.h>

// 以 UART 外设为例（假设的寄存器布局）
typedef struct {
    volatile uint32_t DR;       // 数据寄存器    (偏移 0x00)
    volatile uint32_t SR;       // 状态寄存器    (偏移 0x04)
    volatile uint32_t CR1;      // 控制寄存器 1  (偏移 0x08)
    volatile uint32_t CR2;      // 控制寄存器 2  (偏移 0x0C)
    volatile uint32_t BRR;      // 波特率寄存器  (偏移 0x10)
    const  volatile uint32_t FR; // 标志寄存器    (偏移 0x14)
} UART_Reg;

// 将基地址映射为结构体指针
#define UART1_BASE  ((UART_Reg *)0x40011000)
#define UART2_BASE  ((UART_Reg *)0x40011400)

// 使用
void uart_init(void) {
    UART1_BASE->CR1 = 0x200;      // 使能 UART
    UART1_BASE->BRR = 0x341;      // 设置波特率
}

void uart_send_char(char c) {
    // 等待发送寄存器空
    while (!(UART1_BASE->SR & (1 << 7)));
    UART1_BASE->DR = c;
}

char uart_receive_char(void) {
    // 等待接收数据可用
    while (!(UART1_BASE->FR & (1 << 0)));
    return (char)(UART1_BASE->DR);
}
```

### volatile 关键字的作用

在寄存器映射中，`volatile` 关键字告诉编译器不要优化对该变量的访问——每次读写都从内存地址直接操作。

```c
// 没有 volatile 的后果
void wait_for_flag(void) {
    while ((UART1_BASE->SR & 0x80) == 0) {
        // 编译器可能优化为：
        // 一次读取 SR，然后无限循环（因为编译器认为 SR 不会改变）
    }
}

// 声明为 volatile 后，每次循环都会重新读取 SR
// volatile uint32_t SR;
```

### DMA 描述符

```c
#include <stdint.h>

// DMA 描述符（常见于 STM32、NXP 等 MCU）
struct DMA_Descriptor {
    volatile uint32_t source_addr;      // 源地址
    volatile uint32_t dest_addr;        // 目的地址
    volatile uint32_t control;           // 控制字（传输大小、burst 等）
    volatile uint32_t next_desc;         // 下一个描述符地址（链表模式）
};

// DMA 传输链表
struct DMA_Descriptor desc_pool[4] __attribute__((aligned(16)));

void dma_setup_transfer(struct DMA_Descriptor *desc,
                        void *src, void *dst, uint32_t len) {
    desc->source_addr = (uint32_t)(uintptr_t)src;
    desc->dest_addr   = (uint32_t)(uintptr_t)dst;
    desc->control     = len;
    desc->next_desc   = 0;  // 最后一个描述符
}
```

### 设备描述符模式

嵌入式驱动开发中常用的一种设计模式：将设备信息封装在结构体里。

```c
#include <stdint.h>
#include <stdio.h>

// 设备的通用接口（函数指针）
struct Device;
typedef int  (*device_init_t)(struct Device *dev);
typedef int  (*device_read_t)(struct Device *dev, uint8_t *buf, uint32_t len);
typedef int  (*device_write_t)(struct Device *dev, const uint8_t *buf, uint32_t len);

struct Device {
    const char    *name;
    uint32_t       base_addr;
    uint32_t       irq_num;
    void          *private_data;    // 指向设备特定的附加数据

    // 操作函数指针
    device_init_t  init;
    device_read_t  read;
    device_write_t write;
};

// 具体设备实例
struct Device uart1 = {
    .name = "UART1",
    .base_addr = 0x40011000,
    .irq_num = 37,
    .init = uart_init,
    .read = uart_read,
    .write = uart_write
};

// 统一初始化所有设备
int init_all_devices(struct Device *devs[], int count) {
    for (int i = 0; i < count; i++) {
        if (devs[i]->init(devs[i]) != 0) {
            fprintf(stderr, "设备 %s 初始化失败\n", devs[i]->name);
            return -1;
        }
    }
    return 0;
}
```

