### 练习 5（Bonus）：实现简单的配置文件解析器

编写一个函数，解析如下格式的配置文件：

```
# 这是注释
baudrate=115200
parity=N
databits=8
stopbits=1
device=/dev/ttyUSB0
```

要求：
1. 跳过空行和 `#` 开头的注释行
2. 将每行的键值对存入结构体数组
3. 提供通过键名查找值的函数

```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_CONFIG_ENTRIES 32
#define MAX_KEY_LEN 64
#define MAX_VAL_LEN 128

typedef struct {
    char key[MAX_KEY_LEN];
    char value[MAX_VAL_LEN];
} ConfigEntry;

typedef struct {
    ConfigEntry entries[MAX_CONFIG_ENTRIES];
    int count;
} Config;

// 从文件加载配置
int config_load(Config *cfg, const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) return -1;

    char line[256];
    cfg->count = 0;

    while (fgets(line, sizeof(line), fp) && cfg->count < MAX_CONFIG_ENTRIES) {
        // 跳过空行和注释
        if (line[0] == '\n' || line[0] == '#') continue;

        // 去除末尾换行符
        line[strcspn(line, "\n")] = '\0';

        // 查找 '=' 分隔符
        char *eq = strchr(line, '=');
        if (eq == NULL) continue;

        // 分割键值
        *eq = '\0';
        strncpy(cfg->entries[cfg->count].key, line, MAX_KEY_LEN - 1);
        strncpy(cfg->entries[cfg->count].value, eq + 1, MAX_VAL_LEN - 1);
        cfg->count++;
    }

    fclose(fp);
    return cfg->count;
}

// 按键查找值
const char *config_get(const Config *cfg, const char *key) {
    for (int i = 0; i < cfg->count; i++) {
        if (strcmp(cfg->entries[i].key, key) == 0) {
            return cfg->entries[i].value;
        }
    }
    return NULL;
}

int main(void) {
    Config cfg;
    if (config_load(&cfg, "config.txt") < 0) {
        perror("config_load");
        return 1;
    }

    const char *baud = config_get(&cfg, "baudrate");
    if (baud) printf("波特率: %s\n", baud);

    const char *device = config_get(&cfg, "device");
    if (device) printf("设备: %s\n", device);

    return 0;
}
```

