### 题目 7：分析以下循环的时间复杂度（含特殊边界）

（虚拟电商公司乙 2021 校招）

```c
int func(int n) {
    int sum = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = i; j <= n; j += i) {
            sum++;
        }
    }
    return sum;
}
```

**答案与解析：**

外层循环 i 从 1 到 n，执行 n 次。内层循环 j 从 i 开始，步长为 i，即 j = i, 2i, 3i, ... ≤ n，因此内层执行次数为 n/i。

总执行次数：
```
T(n) = n/1 + n/2 + n/3 + ... + n/n
     = n × (1 + 1/2 + 1/3 + ... + 1/n)
     = n × H(n)         // H(n) 为调和数
```

调和数 H(n) ≈ ln n + γ（γ ≈ 0.577，欧拉常数），因此：

**时间复杂度：O(n log n)**

**嵌入式启示**：这种"跳跃式内层循环"的模式在筛法（如素数筛选）中常见。当 n=10⁵ 时，实际执行次数约 n×ln(10⁵) ≈ 1.15×10⁶，远小于 O(n²) 的 10¹⁰，对嵌入式场景是可接受的。这也说明了**大 O 表示法的常数项不可忽视**——同样的 O(n log n) 可能比另一个 O(n log n) 快数倍。

# 单链表

## 基本概念

### 数据节点定义

```c
struct node
{
    int data;           // 数据域：用来保存数据
    struct node *next;  // 指针域：用来保存逻辑关系（指向下一个节点）
};
```

### 静态建立链表

保存 (1, 5, 4, 3, 2)：

```c
#include <stdio.h>
#include <stdlib.h>

struct node
{
    int data;
    struct node *next;
};

int main()
{
    struct node a1, a2, a3, a4, a5;
    struct node *p = &a1;

    // 保存数据
    a1.data = 1;
    a2.data = 5;
    a3.data = 4;
    a4.data = 3;
    a5.data = 2;

    // 保存关系
    a1.next = &a2;
    a2.next = &a3;
    a3.next = &a4;
    a4.next = &a5;
    a5.next = NULL;

    // 遍历打印
    while (p != NULL)
    {
        printf("%d ", p->data);
        p = p->next;
    }
    printf("\n");
}
```

### 动态建立链表

```c
int d;
while(1)
{
    scanf("%d", &d);
    if(d == 0)
    {
        break;
    }
    struct node *p = (struct node *)malloc(sizeof(struct node));
    p->data = d;
    p->next = NULL;
}
```

---

## 单链表的主要操作：增删改查

### 头文件 Linklist.h

```c
#include <stdio.h>
#include <stdlib.h>
#ifndef __LINKLIST_H__
#define __LINKLIST_H__

struct node
{
    int data;          // 数据域
    struct node *next; // 指针域
};

// 头结点
struct h_node
{
    struct node *first; // 整个链表的第一个节点
    struct node *last;  // 整个链表的最后一个节点
};

struct h_node *Great_h_node(void);      // 创建一个头结点
struct node *Great_node(void);          // 创建一个链表（增）
struct node *Great_increasing(void);    // 插入排序创建增序链表
struct node *delect_x(struct node *h, int x);  // 删除节点（删）
struct node *change_x(struct node *h, int x);  // 修改节点（改）
void find_x(struct node *h, int x);     // 查找节点（查）
void printf_linklist(struct node *h);   // 打印链表
void destroy_linklist(struct node *h);  // 销毁链表

#endif
```

### 增 — 创建一个链表

**尾插法**（打印顺序 = 输入顺序）与**头插法**（打印顺序 = 输入逆序）：

```c
/*
 * Great_node:
 *   创建一个链表
 *   返回值: 创建链表的第一个节点的地址
 */
struct node *Great_node(void)
{
    int d;                     // 用来保存数据域
    struct node *last = NULL;  // 用来保存最后一个节点
    struct node *first = NULL; // 用来保存链表的第一个节点

    while (1)
    {
        scanf("%d", &d);
        if (d == 0)
        {
            break;
        }
        struct node *p = (struct node *)malloc(sizeof(struct node));
        p->data = d;
        p->next = NULL;
        if (first == NULL)
        {
            first = p;
            last = p;
        }
        else
        {
            // 尾插法:
            // last->next = p;
            // last = p;

            // 头插法:
            p->next = first;
            first = p;
        }
    }
    return first;
}
```

### 删 — 删除链表中 x 对应的节点

```c
/*
 * delect_x:
 *   删除链表中 x 对应的那个节点
 *   @h: 链表的第一个节点
 *   @x: 要删除的数据
 *   返回值: 返回链表的首节点
 */
struct node *delect_x(struct node *h, int x)
{
    struct node *pr = NULL; // 指向找到的节点的上一个节点
    struct node *px = h;    // 用来找要删除的节点

    while (px != NULL)
    {
        if (px->data == x)
        {
            break;  // 找到了！
        }
        pr = px;
        px = px->next;
    }

    if (px == h)  // 删除的是第一个节点
    {
        h = h->next;
        px->next = NULL;
        free(px);
    }
    else           // 删除的是中间或最后节点
    {
        pr->next = px->next;
        px->next = NULL;
        free(px);
    }
    return h;
}
```

### 查 — 在链表中查找元素

```c
/*
 * find_x:
 *   遍历链表找到 x
 *   @h: 链表的首节点
 *   @x: 要查找的元素值
 */
void find_x(struct node *h, int x)
{
    if (h == NULL)
    {
        return;
    }
    while (h != NULL)
    {
        if (h->data == x)
        {
            printf("%d\n", h->data);
            return;
        }
        h = h->next;
    }
    printf("没找到\n");
}
```

### 打印链表

```c
void printf_linklist(struct node *h)
{
    if (h == NULL)
    {
        return;
    }
    while (h != NULL)
    {
        printf("%d ", h->data);
        h = h->next;
    }
    printf("\n");
}
```

### 销毁链表

```c
void destroy_linklist(struct node *h)
{
    if (h == NULL)
    {
        return;
    }
    struct node *px = h;    // px 用来遍历链表的每一个节点
    struct node *pr = NULL; // pr 用来做事（干掉一个节点）
    while (px != NULL)
    {
        pr = px;
        px = px->next;
        pr->next = NULL;
        free(pr);
    }
}
```

