## 双向链表的主要操作

### 增 — 创建一个带头结点的双向链表

```c
/*
 * Cretat_linklist:
 *   创建一个带有头结点的双向链表
 *   返回值: 头结点
 */
struct h_node *Cretat_linklist(struct h_node *l)
{
    int d;
    struct node *p = NULL;
    while (1)
    {
        scanf("%d", &d);
        if (d == 0)
        {
            break;
        }
        p = (struct node *)malloc(sizeof(struct node));
        p->data = d;
        p->next = NULL;
        p->prev = NULL;
        if (l->first == NULL)
        {
            l->first = p;
            l->last = p;
        }
        else
        {
            // 尾插法
            l->last->next = p;
            p->prev = l->last;
            l->last = p;
        }
    }
    return l;
}
```

### 插入排序

```c
void insert_sort(struct h_node *l)
{
    int d;
    struct node *p = NULL;
    struct node *px = NULL;
    while (1)
    {
        scanf("%d", &d);
        if (d == 0)
        {
            break;
        }
        p = (struct node *)malloc(sizeof(struct node));
        p->data = d;
        p->next = NULL;
        p->prev = NULL;
        if (l->first == NULL)
        {
            l->first = p;
            l->last = p;
        }
        else
        {
            px = l->first;
            while (px)
            {
                if (px->data > p->data)
                {
                    break;  // 找到插入位置
                }
                px = px->next;
            }
            if (px == l->first)      // 头插法
            {
                l->first = p;
                p->next = px;
                px->prev = p;
            }
            else if (px == NULL)     // 尾插法
            {
                l->last->next = p;
                p->prev = l->last;
                l->last = p;
            }
            else                     // 中间插入
            {
                px->prev->next = p;
                p->prev = px->prev;
                p->next = px;
                px->prev = p;
            }
        }
    }
}
```

### 打印链表（正序 + 倒序）

```c
void printf_linklist(struct h_node *l)
{
    if (l->first == NULL)
    {
        return;
    }
    // 正序打印
    struct node *p = l->first;
    while (p)
    {
        printf("%d ", p->data);
        p = p->next;
    }
    printf("\n");

    // 倒序打印（利用 prev 指针）
    p = l->last;
    while (p)
    {
        printf("%d ", p->data);
        p = p->prev;
    }
    printf("\n");
}
```

### 删 — 删除一个节点

```c
void delete_x(struct h_node *l, int x)
{
    if (l->first == NULL)
    {
        return;
    }
    struct node *px = l->first;
    while (px)
    {
        if (px->data == x)
        {
            break;  // 找到了！
        }
        px = px->next;
    }

    if (px == l->first)  // 删除第一个节点
    {
        l->first = l->first->next;
        l->first->prev = NULL;
        px->next = NULL;
        free(px);
    }
    else if (px->next == NULL)  // 删除最后一个节点
    {
        l->last = px->prev;
        l->last->next = NULL;
        px->prev = NULL;
        free(px);
    }
    else  // 删除中间节点
    {
        px->prev->next = px->next;
        px->next->prev = px->prev;
        px->next = NULL;
        px->prev = NULL;
        free(px);
    }
}
```

### 删 — 删除所有值为 x 的节点

```c
void delete_all_x(struct h_node *l, int x)
{
    if (l->first == NULL)
    {
        return;
    }
    struct node *px = l->first;
    struct node *pr = NULL;
    while (px)
    {
        if (px->data == x)
        {
            if (px == l->first)
            {
                l->first = l->first->next;
                l->first->prev = NULL;
                px->next = NULL;
                free(px);
                px = l->first;
            }
            else if (px->next == NULL)
            {
                l->last = px->prev;
                l->last->next = NULL;
                px->prev = NULL;
                free(px);
                px = NULL;
            }
            else
            {
                pr = px->next;
                px->prev->next = px->next;
                px->next->prev = px->prev;
                px->next = NULL;
                px->prev = NULL;
                free(px);
                px = pr;
            }
        }
        else
        {
            px = px->next;
        }
    }
}
```

