## 链式队列

用带头结点的双向链表实现。

### 数据类型定义

```c
// 数据节点
struct node
{
    int data;
    struct node *next;
    struct node *prev;
};

// 头结点
struct h_node
{
    struct node *front; // 指向队头节点
    struct node *rear;  // 指向队尾节点
    int length;         // 数据节点个数
};
```

### 实现

```c
// 创建队列
struct h_node *Creat_queue(void)
{
    struct h_node *p = (struct h_node *)malloc(sizeof(struct h_node));
    p->front = NULL;
    p->rear = NULL;
    p->length = 0;
    return p;
}

// 元素入队（尾插法）
void Enqueue(struct h_node *l, int x)
{
    if (l == NULL) return;
    struct node *p = (struct node *)malloc(sizeof(struct node));
    p->data = x;
    p->next = NULL;
    p->prev = NULL;
    if (l->rear == NULL)
    {
        l->front = p;
        l->rear = p;
        ++l->length;
    }
    else
    {
        l->rear->next = p;
        p->prev = l->rear;
        l->rear = p;
        ++l->length;
    }
}

// 元素出队（删除第一个节点）
void Outqueue(struct h_node *l)
{
    if (l == NULL) return;
    if (l->front == l->rear && l->length == 1)  // 只有一个元素
    {
        free(l->front);
        l->front = NULL;
        l->rear = NULL;
        l->length = 0;
    }
    else
    {
        l->front = l->front->next;
        l->front->prev->next = NULL;
        free(l->front->prev);
        l->front->prev = NULL;
        --l->length;
    }
}

// 清空队列
void Clearqueue(struct h_node *l)
{
    if (l == NULL) return;
    while (l->front != NULL)
    {
        Outqueue(l);
    }
}

// 销毁队列
void Destroyqueue(struct h_node *l)
{
    if (l == NULL) return;
    Clearqueue(l);
    free(l);
}

// 判断队列是否为空
int QueueisEmpty(struct h_node *l)
{
    if (l == NULL) return 1;
    if (l->front == NULL && l->rear == NULL && l->length == 0) return 1;
    return 0;
}
```

