## 编程练习

### 练习1：用函数指针实现回调排序（冒泡排序接受比较函数）

实现一个冒泡排序函数 `bubble_sort`，接受一个函数指针参数作为比较器，支持升序和降序两种比较。

```c
#include <stdio.h>
#include <stdbool.h>

// 比较函数类型
typedef int (*cmp_func_t)(const void *, const void *);

int cmp_asc(const void *a, const void *b)
{
    int ia = *(const int *)a;
    int ib = *(const int *)b;
    return (ia > ib) - (ia < ib);
}

int cmp_desc(const void *a, const void *b)
{
    int ia = *(const int *)a;
    int ib = *(const int *)b;
    return (ib > ia) - (ib < ia);
}

void bubble_sort(void *base, size_t n, size_t size, cmp_func_t cmp)
{
    char *arr = (char *)base;

    for (size_t i = 0; i < n - 1; i++) {
        for (size_t j = 0; j < n - 1 - i; j++) {
            char *p = arr + j * size;
            char *q = arr + (j + 1) * size;
            if (cmp(p, q) > 0) {
                // 交换
                for (size_t k = 0; k < size; k++) {
                    char tmp = p[k];
                    p[k] = q[k];
                    q[k] = tmp;
                }
            }
        }
    }
}

void print_array(const int *arr, size_t n)
{
    for (size_t i = 0; i < n; i++)
        printf("%d ", arr[i]);
    printf("\n");
}

int main(void)
{
    int arr[] = {5, 3, 8, 1, 9, 2};
    size_t n = sizeof(arr) / sizeof(arr[0]);

    bubble_sort(arr, n, sizeof(int), cmp_asc);
    print_array(arr, n);   // 1 2 3 5 8 9

    bubble_sort(arr, n, sizeof(int), cmp_desc);
    print_array(arr, n);   // 9 8 5 3 2 1

    return 0;
}
```

### 练习2：动态数组 —— 实现可动态扩容的整数数组

实现一个支持 `append`、`get`、`set`、`size` 和 `destroy` 操作的动态整数数组。

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int *data;
    size_t size;      // 当前元素数
    size_t capacity;  // 已分配容量
} IntArray;

// 初始化
void ia_init(IntArray *arr)
{
    arr->data = NULL;
    arr->size = 0;
    arr->capacity = 0;
}

// 追加元素
int ia_append(IntArray *arr, int val)
{
    if (arr->size == arr->capacity) {
        size_t new_cap = arr->capacity == 0 ? 4 : arr->capacity * 2;
        int *new_data = (int *)realloc(arr->data, new_cap * sizeof(int));
        if (new_data == NULL)
            return -1;
        arr->data = new_data;
        arr->capacity = new_cap;
    }
    arr->data[arr->size++] = val;
    return 0;
}

// 获取元素（返回下标和状态）
int ia_get(const IntArray *arr, size_t index, int *out)
{
    if (index >= arr->size)
        return -1;
    *out = arr->data[index];
    return 0;
}

// 设置元素
int ia_set(IntArray *arr, size_t index, int val)
{
    if (index >= arr->size)
        return -1;
    arr->data[index] = val;
    return 0;
}

// 当前大小
size_t ia_size(const IntArray *arr)
{
    return arr->size;
}

// 销毁
void ia_destroy(IntArray *arr)
{
    free(arr->data);
    arr->data = NULL;
    arr->size = 0;
    arr->capacity = 0;
}

int main(void)
{
    IntArray arr;
    ia_init(&arr);

    for (int i = 0; i < 100; i++)
        ia_append(&arr, i * 10);

    printf("size = %zu\n", ia_size(&arr));  // 100

    int val;
    if (ia_get(&arr, 42, &val) == 0)
        printf("arr[42] = %d\n", val);      // 420

    ia_destroy(&arr);
    return 0;
}
```

### 练习3：简单内存池（嵌入式场景）

实现一个固定大小块的内存分配器，预分配一大块内存，按固定块大小分割。适用于嵌入式系统中避免频繁堆分配碎片化的场景。

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

typedef struct Block {
    struct Block *next;   // 空闲链表指针
} Block;

typedef struct {
    void *pool_start;      // 池起始地址
    size_t block_size;     // 每个块的大小（字节）
    size_t block_count;    // 总块数
    Block *free_list;      // 空闲块链表头
} MemPool;

// 初始化内存池：预分配 block_count × block_size 字节
int mp_init(MemPool *pool, size_t block_size, size_t block_count)
{
    // 确保每个块至少能放下链表指针
    size_t aligned_block = block_size < sizeof(Block) ? sizeof(Block) : block_size;

    pool->pool_start = malloc(aligned_block * block_count);
    if (pool->pool_start == NULL)
        return -1;

    pool->block_size = aligned_block;
    pool->block_count = block_count;

    // 初始化空闲链表
    pool->free_list = (Block *)pool->pool_start;
    Block *current = pool->free_list;
    for (size_t i = 0; i < block_count - 1; i++) {
        current->next = (Block *)((char *)current + aligned_block);
        current = current->next;
    }
    current->next = NULL;

    return 0;
}

// 分配一个块
void *mp_alloc(MemPool *pool)
{
    if (pool->free_list == NULL)
        return NULL;   // 池已满

    Block *block = pool->free_list;
    pool->free_list = block->next;
    return (void *)block;
}

// 释放一个块
void mp_free(MemPool *pool, void *ptr)
{
    if (ptr == NULL)
        return;

    // 检查 ptr 是否属于本池 (范围检查)
    char *start = (char *)pool->pool_start;
    char *end = start + pool->block_size * pool->block_count;
    char *p = (char *)ptr;

    if (p < start || p >= end) {
        printf("警告：释放的指针不属于本内存池\n");
        return;
    }

    // 插入到空闲链表头部
    Block *block = (Block *)ptr;
    block->next = pool->free_list;
    pool->free_list = block;
}

// 销毁内存池
void mp_destroy(MemPool *pool)
{
    free(pool->pool_start);
    pool->pool_start = NULL;
    pool->free_list = NULL;
}

int main(void)
{
    MemPool pool;

    if (mp_init(&pool, 64, 10) != 0) {
        printf("内存池初始化失败\n");
        return 1;
    }

    // 分配几个块
    void *p1 = mp_alloc(&pool);
    void *p2 = mp_alloc(&pool);
    void *p3 = mp_alloc(&pool);

    printf("p1 = %p\n", p1);
    printf("p2 = %p\n", p2);
    printf("p3 = %p\n", p3);

    // 释放后重新分配
    mp_free(&pool, p2);
    void *p4 = mp_alloc(&pool);
    printf("p4 (reuse) = %p (应与 p2 相同)\n", p4);

    mp_destroy(&pool);
    return 0;
}
```

### 练习4：函数指针表 —— 计算器

通过函数指针表实现一个支持加减乘除的计算器。

```c
#include <stdio.h>
#include <stdlib.h>

// 函数指针类型
typedef int (*op_func_t)(int, int);

// 四则运算
int add(int a, int b) { return a + b; }
int sub(int a, int b) { return a - b; }
int mul(int a, int b) { return a * b; }
int divide(int a, int b) { return b != 0 ? a / b : 0; }

// 操作符表
typedef struct {
    char sym;
    op_func_t func;
    const char *name;
} Operator;

int main(void)
{
    Operator ops[] = {
        {'+', add,    "加法"},
        {'-', sub,    "减法"},
        {'*', mul,    "乘法"},
        {'/', divide, "除法"}
    };
    size_t op_count = sizeof(ops) / sizeof(ops[0]);

    int a, b;
    char op;

    printf("请输入表达式（如: 10 + 5）: ");
    if (scanf("%d %c %d", &a, &op, &b) != 3) {
        printf("输入格式错误\n");
        return 1;
    }

    int found = 0;
    for (size_t i = 0; i < op_count; i++) {
        if (ops[i].sym == op) {
            int result = ops[i].func(a, b);
            printf("%s: %d %c %d = %d\n", ops[i].name, a, op, b, result);
            found = 1;
            break;
        }
    }

    if (!found)
        printf("不支持的操作符: %c\n", op);

    return 0;
}
```

