## 结构体与数组

### 结构体数组

```c
#include <stdio.h>
#include <string.h>

struct Student {
    char name[32];
    int  age;
};

int main(void) {
    // 声明结构体数组
    struct Student class[3];

    // 初始化
    strcpy(class[0].name, "张三");
    class[0].age = 20;

    strcpy(class[1].name, "李四");
    class[1].age = 21;

    // 初始化列表方式
    struct Student class2[3] = {
        {"王五", 22},
        {"赵六", 23},
        {"孙七", 24}
    };

    // 遍历
    for (int i = 0; i < 3; i++) {
        printf("%s: %d岁\n", class2[i].name, class2[i].age);
    }

    return 0;
}
```

### 嵌套结构体

```c
#include <stdio.h>

struct Date {
    int year;
    int month;
    int day;
};

struct Employee {
    char      name[32];
    int       id;
    struct    Date hire_date;   // 嵌套结构体
    double    salary;
};

int main(void) {
    struct Employee emp = {
        .name = "张三",
        .id = 1001,
        .hire_date = {2020, 5, 15},  // 嵌套初始化
        .salary = 15000.0
    };

    // 访问嵌套成员
    printf("%s 入职日期: %d-%02d-%02d\n",
           emp.name,
           emp.hire_date.year,
           emp.hire_date.month,
           emp.hire_date.day);

    return 0;
}
```

### 自引用结构体

结构体可以包含指向自身类型的指针。这是**链表、树、图**等数据结构的基础。

```c
#include <stdio.h>
#include <stdlib.h>

// 单向链表节点
struct ListNode {
    int data;
    struct ListNode *next;  // 指向下一个节点
};

// 双向链表节点
struct DoublyListNode {
    int data;
    struct DoublyListNode *prev;
    struct DoublyListNode *next;
};

// 二叉树节点
struct TreeNode {
    int data;
    struct TreeNode *left;
    struct TreeNode *right;
};

int main(void) {
    // 创建三个链表节点
    struct ListNode n1 = {10, NULL};
    struct ListNode n2 = {20, NULL};
    struct ListNode n3 = {30, NULL};

    n1.next = &n2;
    n2.next = &n3;

    // 遍历链表
    for (struct ListNode *p = &n1; p != NULL; p = p->next) {
        printf("%d -> ", p->data);
    }
    printf("NULL\n");

    return 0;
}
```

