## 创建一个带头结点的单链表

```c
#include "Linklist.h"

struct h_node *Great_node(struct h_node *l)
{
    int d;
    struct node *p = NULL;
    while (1)
    {
        scanf("%d", &d);
        if (d == 0)
        {
            break;
        }
        p = (struct node *)malloc(sizeof(struct node));
        p->data = d;
        p->next = NULL;
        if (l->first == NULL)  // 此时没有数据节点
        {
            l->first = p;
            l->last = p;
        }
        else
        {
            // 尾插法
            l->last->next = p;
            l->last = p;

            // 头插法
            // p->next = l->first;
            // l->first = p;
        }
    }
    return l;
}
