## 二、队列 (Queue)

### 定义

队列也是一种**受限的线性表**：允许在一端进行插入操作，另一端进行删除操作。

- **FIFO**：先进先出（First In First Out）
- **队尾 (Rear)**：允许插入元素的一端
- **队头 (Front)**：允许删除元素的一端

### 队列的基本操作

| 操作 | 说明 |
|------|------|
| `InitQueue` | 创建一个队列 |
| `DestroyQueue` | 销毁一个队列 |
| `ClearQueue` | 清空一个队列 |
| `QueueisEmpty` | 判断队列是否为空 |
| `Queuelength` | 求队列长度 |
| `EnQueue` | 进队 |
| `OutQueue` | 出队 |
| `Gethead` | 获取队头元素 |

---

## 顺序队列

### 数据类型定义

```c
#define MAXLEN 1024

struct queue
{
    int data[MAXLEN]; // 队列的数据存储
    int front;        // 队头位置（一维数组的下标）
    int rear;         // 队尾位置（一维数组的下标）
    int length;       // 队列中元素的个数
};
```

### 实现

```c
// 创建队列
struct queue *InitQueue(void)
{
    struct queue *p = (struct queue *)malloc(sizeof(struct queue));
    p->front = -1;
    p->rear = -1;
    p->length = 0;
    return p;
}

// 元素进队
void Enqueue(struct queue *p, int x)
{
    if (p->rear == MAXLEN - 1) return;  // 队列满
    if (p->front == -1)
    {
        p->front = 0;
    }
    p->data[++p->rear] = x;
    ++p->length;
}

// 元素出队
void Outqueue(struct queue *p)
{
    if (p->front == -1 || p->front > p->rear) return;
    ++p->front;
    --p->length;
}

// 清空队列
void Clearqueue(struct queue *p)
{
    if (p->front == -1 && p->rear == -1) return;
    p->front = -1;
    p->rear = -1;
    p->length = 0;
}

// 销毁队列
void Destroyqueue(struct queue *p)
{
    if (p == NULL) return;
    free(p);
}

// 队列长度
int Queuelength(struct queue *p)
{
    if (p == NULL) return 0;
    return p->length;
}
```

---

## 链式队列

用带头结点的双向链表实现。

### 数据类型定义

```c
// 数据节点
struct node
{
    int data;
    struct node *next;
    struct node *prev;
};

// 头结点
struct h_node
{
    struct node *front; // 指向队头节点
    struct node *rear;  // 指向队尾节点
    int length;         // 数据节点个数
};
```

### 实现

```c
// 创建队列
struct h_node *Creat_queue(void)
{
    struct h_node *p = (struct h_node *)malloc(sizeof(struct h_node));
    p->front = NULL;
    p->rear = NULL;
    p->length = 0;
    return p;
}

// 元素入队（尾插法）
void Enqueue(struct h_node *l, int x)
{
    if (l == NULL) return;
    struct node *p = (struct node *)malloc(sizeof(struct node));
    p->data = x;
    p->next = NULL;
    p->prev = NULL;
    if (l->rear == NULL)
    {
        l->front = p;
        l->rear = p;
        ++l->length;
    }
    else
    {
        l->rear->next = p;
        p->prev = l->rear;
        l->rear = p;
        ++l->length;
    }
}

// 元素出队（删除第一个节点）
void Outqueue(struct h_node *l)
{
    if (l == NULL) return;
    if (l->front == l->rear && l->length == 1)  // 只有一个元素
    {
        free(l->front);
        l->front = NULL;
        l->rear = NULL;
        l->length = 0;
    }
    else
    {
        l->front = l->front->next;
        l->front->prev->next = NULL;
        free(l->front->prev);
        l->front->prev = NULL;
        --l->length;
    }
}

// 清空队列
void Clearqueue(struct h_node *l)
{
    if (l == NULL) return;
    while (l->front != NULL)
    {
        Outqueue(l);
    }
}

// 销毁队列
void Destroyqueue(struct h_node *l)
{
    if (l == NULL) return;
    Clearqueue(l);
    free(l);
}

// 判断队列是否为空
int QueueisEmpty(struct h_node *l)
{
    if (l == NULL) return 1;
    if (l->front == NULL && l->rear == NULL && l->length == 0) return 1;
    return 0;
}
```

